CREATE OR REPLACE FUNCTION public.normalize_profile_enrollment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.enrollment_number := nullif(btrim(NEW.enrollment_number), '');
  IF NEW.role = 'supervisor' THEN
    NEW.enrollment_number := NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_last_active_supervisor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_remaining integer;
BEGIN
  -- Prevent assigning super_admin under any circumstance
  IF (TG_OP = 'INSERT' OR TG_OP = 'UPDATE') THEN
    IF NEW.role = 'super_admin'::public.app_role THEN
      RAISE EXCEPTION 'The super admin role has been permanently removed.';
    END IF;
  END IF;

  -- Last active teacher guard
  IF (TG_OP = 'DELETE' AND OLD.role = 'supervisor'::public.app_role AND OLD.active = true) OR
     (TG_OP = 'UPDATE' AND OLD.role = 'supervisor'::public.app_role AND OLD.active = true AND 
      (NEW.active = false OR NEW.role <> 'supervisor'::public.app_role)) THEN
    
    SELECT count(*) INTO v_remaining
    FROM public.profiles
    WHERE role = 'supervisor'::public.app_role
      AND active = true
      AND id <> OLD.id;

    IF v_remaining = 0 THEN
      RAISE EXCEPTION 'Cannot demote, deactivate, or delete the last active teacher (supervisor).';
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.question_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op='INSERT' then
    new.author_id:=auth.uid();
    new.status:='pending';
    new.reviewed_by:=null;
    new.reviewed_at:=null;
    if not public.can_review() then new.is_special:=false; end if;
  elsif public.can_review() then
    if old.author_id is distinct from new.author_id then new.author_id:=old.author_id; end if;
    if old.status is distinct from new.status then
      new.reviewed_by:=auth.uid();
      new.reviewed_at:=now();
    else
      new.reviewed_by:=old.reviewed_by;
      new.reviewed_at:=old.reviewed_at;
    end if;
  else
    new.author_id:=old.author_id;
    new.status:='pending';
    new.reviewed_by:=null;
    new.reviewed_at:=null;
    new.is_special:=old.is_special;
  end if;
  return new;
end $function$

