CREATE OR REPLACE FUNCTION public.activate_member(p_profile_id uuid, p_role text, p_enrollment_number text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  enrollment text;
  selected_role public.app_role;
BEGIN
  IF NOT coalesce(public.current_role() = 'supervisor', false) THEN
    RAISE EXCEPTION 'Only active teachers can activate members';
  END IF;

  IF p_role IS NULL OR p_role NOT IN ('supervisor', 'student_leader', 'student') THEN
    RAISE EXCEPTION 'Choose a valid role: supervisor, student_leader, or student';
  END IF;
  selected_role := p_role::public.app_role;

  SELECT coalesce(
    nullif(btrim(p_enrollment_number), ''),
    nullif(btrim(p.enrollment_number), ''),
    nullif(btrim(u.raw_user_meta_data->>'enrollment_number'), '')
  ) INTO enrollment
  FROM public.profiles p
  LEFT JOIN auth.users u ON u.id = p.id
  WHERE p.id = p_profile_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member profile was not found';
  END IF;

  IF selected_role IN ('student', 'student_leader') AND enrollment IS NULL THEN
    RAISE EXCEPTION 'Enrollment number was not saved at signup; ask the student to provide it';
  END IF;

  IF selected_role = 'supervisor' THEN
    enrollment := NULL;
  END IF;

  UPDATE public.profiles
  SET role = selected_role,
      active = true,
      requested_role = NULL,
      enrollment_number = enrollment
  WHERE id = p_profile_id AND active = false;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'This member is not waiting for activation';
  END IF;

  RETURN true;
EXCEPTION
  WHEN unique_violation THEN
    RAISE EXCEPTION 'That enrollment number is already assigned to another member';
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_manage_profile(p_profile_id uuid, p_role text, p_enrollment_number text DEFAULT NULL::text, p_active boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_role app_role;
  v_target_profile profiles%ROWTYPE;
  v_new_role app_role;
BEGIN
  -- Verify caller is an active teacher (supervisor)
  SELECT role INTO v_caller_role
  FROM public.profiles
  WHERE id = auth.uid() AND active = true;

  IF v_caller_role IS NULL OR v_caller_role <> 'supervisor'::app_role THEN
    RAISE EXCEPTION 'Only active teachers can change member roles and status.';
  END IF;

  -- Block any attempt to assign the deprecated super_admin role
  IF trim(p_role) = 'super_admin' THEN
    RAISE EXCEPTION 'The super admin role has been removed. Choose student, student_leader, or supervisor.';
  END IF;

  -- Validate requested role against app_role enum
  BEGIN
    v_new_role := trim(p_role)::app_role;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'Invalid role: %', p_role;
  END;

  -- Validate enrollment number requirement for students
  IF v_new_role IN ('student'::app_role, 'student_leader'::app_role) THEN
    IF p_enrollment_number IS NULL OR trim(p_enrollment_number) = '' THEN
      RAISE EXCEPTION 'Enrollment number is required for students and student leaders.';
    END IF;
  END IF;

  UPDATE public.profiles
  SET
    role = v_new_role,
    enrollment_number = CASE 
      WHEN v_new_role IN ('student'::app_role, 'student_leader'::app_role) THEN trim(p_enrollment_number) 
      ELSE NULL 
    END,
    active = p_active,
    requested_role = NULL
  WHERE id = p_profile_id
  RETURNING * INTO v_target_profile;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Member profile not found.';
  END IF;

  RETURN jsonb_build_object(
    'id', v_target_profile.id,
    'full_name', v_target_profile.full_name,
    'role', v_target_profile.role,
    'active', v_target_profile.active,
    'enrollment_number', v_target_profile.enrollment_number
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.assign_duty_manually(p_duty_date date, p_student_id uuid, p_target_count integer DEFAULT 5)
 RETURNS TABLE(duty_id uuid, duty_date date, student_id uuid, full_name text, target_count integer, rotation_cycle integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c integer; new_id uuid;
begin
  if not public.can_manage() then raise exception 'Not permitted'; end if;
  if p_duty_date is null or p_target_count not between 1 and 20 then raise exception 'Choose a valid date and question target'; end if;
  if exists(select 1 from public.duties as existing where existing.duty_date=p_duty_date) then raise exception 'A duty is already assigned for this date'; end if;
  if not exists(select 1 from public.profiles as member where member.id=p_student_id and member.active and member.role in ('student','student_leader')) then
    raise exception 'Choose an active student';
  end if;

  insert into public.duty_rotation_state(singleton,current_cycle) values(true,1) on conflict(singleton) do nothing;
  perform 1 from public.duty_rotation_state as rotation where rotation.singleton=true for update;
  select rotation.current_cycle into c from public.duty_rotation_state as rotation where rotation.singleton=true;
  c:=coalesce(c,1);
  if not exists(select 1 from public.duty_rotation_members as member where member.cycle_no=c) then
    insert into public.duty_rotation_members(cycle_no,profile_id,position)
      select c,p.id,row_number() over(order by random())::integer from public.profiles as p
      where p.active and p.role in ('student','student_leader');
  end if;
  insert into public.duty_rotation_members(cycle_no,profile_id,position)
    select c,p_student_id,coalesce((select max(member.position)+1 from public.duty_rotation_members as member where member.cycle_no=c),1)
    where not exists(select 1 from public.duty_rotation_members as member where member.cycle_no=c and member.profile_id=p_student_id);
  if exists(select 1 from public.duty_rotation_members as member where member.cycle_no=c and member.profile_id=p_student_id and member.assigned_on is not null) then
    raise exception 'This student already had a turn in the current rotation';
  end if;

  insert into public.duties(duty_date,student_id,target_count,assigned_by,rotation_cycle,duty_status,status_updated_by)
    values(p_duty_date,p_student_id,p_target_count,auth.uid(),c,'assigned',auth.uid()) returning id into new_id;
  update public.duty_rotation_members as member set assigned_on=p_duty_date where member.cycle_no=c and member.profile_id=p_student_id;
  insert into public.duty_change_log(duty_id,action,new_student_id,reason,changed_by)
    values(new_id,'manually_assigned',p_student_id,'Manually assigned by staff',auth.uid());
  return query select new_id,p_duty_date,p.id,p.full_name,p_target_count,c from public.profiles as p where p.id=p_student_id;
end $function$

CREATE OR REPLACE FUNCTION public.assign_next_duty(p_duty_date date, p_target_count integer DEFAULT 5)
 RETURNS TABLE(duty_id uuid, duty_date date, student_id uuid, full_name text, target_count integer, rotation_cycle integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c integer;
  chosen uuid;
  new_id uuid;
begin
  if not public.can_manage() then raise exception 'Not permitted'; end if;
  if p_duty_date is null or p_target_count not between 1 and 20 then
    raise exception 'Invalid duty date or target';
  end if;
  if exists(select 1 from public.duties d where d.duty_date = p_duty_date) then
    raise exception 'A duty is already assigned for that date';
  end if;

  -- Ensure the singleton exists before reading and locking it. Without this row,
  -- c would be NULL and the NOT NULL cycle_no insert would fail.
  insert into public.duty_rotation_state(singleton, current_cycle)
  values (true, 1)
  on conflict (singleton) do nothing;
  perform 1 from public.duty_rotation_state where singleton = true for update;
  select current_cycle into c
  from public.duty_rotation_state where singleton = true;

  if c is null then raise exception 'Could not initialize duty rotation cycle'; end if;

  if not exists(select 1 from public.duty_rotation_members where cycle_no = c) then
    insert into public.duty_rotation_members(cycle_no, profile_id, position)
    select c, p.id, row_number() over(order by random())::integer
    from public.profiles p
    where p.active and p.role in ('student', 'student_leader');
  end if;

  if not exists(
    select 1
    from public.duty_rotation_members rm
    join public.profiles p on p.id = rm.profile_id
    where rm.cycle_no = c
      and rm.assigned_on is null
      and p.active and p.role in ('student', 'student_leader')
      and not exists(
        select 1 from public.duty_availability a
        where a.profile_id = rm.profile_id
          and a.availability_date = p_duty_date
          and a.status in ('leave', 'unavailable')
      )
  ) then
    if exists(
      select 1
      from public.duty_rotation_members rm
      join public.profiles p on p.id = rm.profile_id
      where rm.cycle_no = c
        and rm.assigned_on is null
        and p.active and p.role in ('student', 'student_leader')
    ) then
      raise exception 'All remaining students are marked on leave or unavailable for this date';
    end if;

    update public.duty_rotation_state
    set current_cycle = current_cycle + 1
    where singleton = true
    returning current_cycle into c;

    insert into public.duty_rotation_members(cycle_no, profile_id, position)
    select c, p.id, row_number() over(order by random())::integer
    from public.profiles p
    where p.active and p.role in ('student', 'student_leader');
  end if;

  insert into public.duty_rotation_members(cycle_no, profile_id, position)
  select c, p.id,
    coalesce((select max(position)
              from public.duty_rotation_members
              where cycle_no = c), 0) + 1
  from public.profiles p
  where p.active and p.role in ('student', 'student_leader')
    and not exists(
      select 1 from public.duty_rotation_members rm
      where rm.cycle_no = c and rm.profile_id = p.id
    );

  select rm.profile_id into chosen
  from public.duty_rotation_members rm
  join public.profiles p on p.id = rm.profile_id
    and p.active and p.role in ('student', 'student_leader')
  where rm.cycle_no = c
    and rm.assigned_on is null
    and not exists(
      select 1 from public.duty_availability a
      where a.profile_id = rm.profile_id
        and a.availability_date = p_duty_date
        and a.status in ('leave', 'unavailable')
    )
  order by rm.position
  limit 1;

  if chosen is null then
    raise exception 'No available students are eligible for duty on this date';
  end if;

  insert into public.duties(duty_date, student_id, target_count, assigned_by, rotation_cycle)
  values (p_duty_date, chosen, p_target_count, auth.uid(), c)
  returning id into new_id;

  update public.duty_rotation_members
  set assigned_on = p_duty_date
  where cycle_no = c and profile_id = chosen;

  return query
  select new_id, p_duty_date, chosen, p.full_name, p_target_count, c
  from public.profiles p where p.id = chosen;
end;
$function$

CREATE OR REPLACE FUNCTION public.attach_questions_to_duty(p_duty_id uuid, p_question_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cur_duty public.duties%rowtype; have integer; want integer; ok integer;
begin
  select t.* into cur_duty from public.duties as t where t.id=p_duty_id for update;
  if not found then raise exception 'Duty not found'; end if;
  if not (public.can_review() or cur_duty.student_id=auth.uid()) then raise exception 'Not permitted'; end if;
  if cur_duty.duty_status in ('excused','missed') then raise exception 'This duty is closed'; end if;
  want:=coalesce(array_length(p_question_ids,1),0);
  if want=0 then raise exception 'Choose at least one question'; end if;
  select count(*) into have from public.duty_questions as dq join public.questions as q on q.id=dq.question_id
    where dq.duty_id=cur_duty.id and q.author_id=cur_duty.student_id;
  if have+want>cur_duty.target_count then
    raise exception 'This duty needs only % more question(s)',greatest(cur_duty.target_count-have,0);
  end if;
  select count(*) into ok from public.questions as q
    where q.id=any(p_question_ids) and q.author_id=cur_duty.student_id
      and not exists(select 1 from public.duty_questions as x where x.question_id=q.id);
  if ok<>want then raise exception 'Some questions are not yours or already count for another duty'; end if;
  insert into public.duty_questions(question_id,duty_id,linked_by)
    select q.id,cur_duty.id,auth.uid() from public.questions as q where q.id=any(p_question_ids);
  return want;
end $function$

CREATE OR REPLACE FUNCTION public.autosave_quiz_progress(p_quiz_id uuid, p_answers jsonb, p_time_taken_seconds integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_student_id uuid;
  v_quiz record;
  v_attempt record;
  v_total int := 0;
  v_answers jsonb;
begin
  v_student_id := auth.uid();
  if v_student_id is null then
    raise exception 'Not authenticated';
  end if;
  if p_answers is not null and jsonb_typeof(p_answers) <> 'object' then
    raise exception 'Answers must be an object';
  end if;
  v_answers := coalesce(p_answers, '{}'::jsonb);

  select id, opens_at, closes_at, ended_early_at, is_hidden
  into v_quiz
  from public.quizzes
  where id = p_quiz_id;

  if not found then
    raise exception 'Quiz not found';
  end if;
  if v_quiz.ended_early_at is not null or clock_timestamp() > v_quiz.closes_at then
    return jsonb_build_object(
      'success', false,
      'status', 'closed',
      'message', 'Quiz has closed'
    );
  end if;

  select id, status
  into v_attempt
  from public.quiz_attempts
  where quiz_id = p_quiz_id and student_id = v_student_id;

  if found and v_attempt.status = 'submitted' then
    return jsonb_build_object(
      'success', false,
      'status', 'submitted',
      'message', 'Quiz already submitted'
    );
  end if;

  select count(*) into v_total
  from public.quiz_questions
  where quiz_id = p_quiz_id;

  insert into public.quiz_attempts (
    quiz_id,
    student_id,
    status,
    autosaved_answers,
    answers,
    time_taken_seconds,
    total,
    started_at,
    updated_at
  )
  values (
    p_quiz_id,
    v_student_id,
    'in_progress',
    v_answers,
    v_answers,
    coalesce(p_time_taken_seconds, 0),
    v_total,
    clock_timestamp(),
    clock_timestamp()
  )
  on conflict (quiz_id, student_id) do update set
    autosaved_answers =
      coalesce(public.quiz_attempts.autosaved_answers, '{}'::jsonb)
      || excluded.autosaved_answers,
    answers =
      coalesce(public.quiz_attempts.answers, '{}'::jsonb)
      || excluded.answers,
    time_taken_seconds =
      coalesce(p_time_taken_seconds, public.quiz_attempts.time_taken_seconds),
    updated_at = clock_timestamp()
  where public.quiz_attempts.status = 'in_progress';

  return jsonb_build_object(
    'success', true,
    'status', 'in_progress',
    'saved_at', clock_timestamp()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.bulk_assign_duties(p_dates date[], p_student_ids uuid[], p_target_count integer DEFAULT 5)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c integer; n integer; i integer; v_date date; v_student uuid; sname text; new_id uuid;
  today_ist date:=(now() at time zone 'Asia/Kolkata')::date;
begin
  if not public.can_manage() then raise exception 'Not permitted'; end if;
  n:=coalesce(array_length(p_dates,1),0);
  if n=0 or n<>coalesce(array_length(p_student_ids,1),0) then raise exception 'Provide the same number of dates and students'; end if;
  if n>100 then raise exception 'Assign at most 100 duties at once'; end if;
  if p_target_count is null or p_target_count not between 1 and 20 then raise exception 'Choose a question target between 1 and 20'; end if;
  if (select count(distinct x) from unnest(p_dates) as x)<>n then raise exception 'Each date can be used only once'; end if;
  if (select count(distinct x) from unnest(p_student_ids) as x)<>n then raise exception 'Each student can be assigned only once'; end if;

  insert into public.duty_rotation_state(singleton,current_cycle) values(true,1) on conflict(singleton) do nothing;
  perform 1 from public.duty_rotation_state as rs where rs.singleton=true for update;
  select rs.current_cycle into c from public.duty_rotation_state as rs where rs.singleton=true;
  c:=coalesce(c,1);
  if not exists(select 1 from public.duty_rotation_members as m where m.cycle_no=c) then
    insert into public.duty_rotation_members(cycle_no,profile_id,position)
      select c,p.id,row_number() over(order by random())::integer from public.profiles as p
      where p.active and p.role in ('student','student_leader');
  end if;
  -- everyone already had a turn: this batch starts the next rotation
  if not exists(select 1 from public.duty_rotation_members as m join public.profiles as p on p.id=m.profile_id
      where m.cycle_no=c and m.assigned_on is null and p.active and p.role in ('student','student_leader')) then
    update public.duty_rotation_state set current_cycle=current_cycle+1 where singleton=true returning current_cycle into c;
    insert into public.duty_rotation_members(cycle_no,profile_id,position)
      select c,p.id,row_number() over(order by random())::integer from public.profiles as p
      where p.active and p.role in ('student','student_leader');
  end if;

  for i in 1..n loop
    v_date:=p_dates[i]; v_student:=p_student_ids[i]; sname:=null;
    if v_date<today_ist then raise exception 'Cannot assign a duty in the past (%)',v_date; end if;
    if exists(select 1 from public.duties as x where x.duty_date=v_date) then raise exception 'A duty is already assigned for %',v_date; end if;
    select p.full_name into sname from public.profiles as p where p.id=v_student and p.active and p.role in ('student','student_leader');
    if sname is null then raise exception 'Choose only active students'; end if;
    if exists(select 1 from public.duty_availability as av where av.profile_id=v_student and av.availability_date=v_date and av.status in ('leave','unavailable')) then
      raise exception '% is unavailable on %',sname,v_date;
    end if;
    insert into public.duty_rotation_members(cycle_no,profile_id,position)
      select c,v_student,coalesce((select max(m.position)+1 from public.duty_rotation_members as m where m.cycle_no=c),1)
      where not exists(select 1 from public.duty_rotation_members as m where m.cycle_no=c and m.profile_id=v_student);
    if exists(select 1 from public.duty_rotation_members as m where m.cycle_no=c and m.profile_id=v_student and m.assigned_on is not null) then
      raise exception '% already had a turn in this rotation',sname;
    end if;
    insert into public.duties(duty_date,student_id,target_count,assigned_by,rotation_cycle,duty_status,status_updated_by)
      values(v_date,v_student,p_target_count,auth.uid(),c,'assigned',auth.uid()) returning id into new_id;
    update public.duty_rotation_members as m set assigned_on=v_date where m.cycle_no=c and m.profile_id=v_student;
    insert into public.duty_change_log(duty_id,action,new_student_id,reason,changed_by)
      values(new_id,'bulk_assigned',v_student,'Assigned in bulk by staff',auth.uid());
  end loop;
  return n;
end $function$

CREATE OR REPLACE FUNCTION public.check_last_active_supervisor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_remaining integer;
BEGIN
  -- Prevent assigning super_admin under any circumstance
  IF (TG_OP = 'INSERT' OR TG_OP = 'UPDATE') THEN
    IF NEW.role = 'super_admin'::public.app_role THEN
      RAISE EXCEPTION 'The super admin role has been permanently removed.';
    END IF;
  END IF;

  -- Last active teacher guard
  IF (TG_OP = 'DELETE' AND OLD.role = 'supervisor'::public.app_role AND OLD.active = true) OR
     (TG_OP = 'UPDATE' AND OLD.role = 'supervisor'::public.app_role AND OLD.active = true AND 
      (NEW.active = false OR NEW.role <> 'supervisor'::public.app_role)) THEN
    
    SELECT count(*) INTO v_remaining
    FROM public.profiles
    WHERE role = 'supervisor'::public.app_role
      AND active = true
      AND id <> OLD.id;

    IF v_remaining = 0 THEN
      RAISE EXCEPTION 'Cannot demote, deactivate, or delete the last active teacher (supervisor).';
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_quiz(p_title text, p_kind quiz_kind, p_question_ids uuid[], p_opens_at timestamp with time zone, p_closes_at timestamp with time zone, p_duration_minutes integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare qid uuid; cnt integer;
begin
 if not public.can_manage() then raise exception 'Not permitted';end if;
 if array_length(p_question_ids,1) is null or p_closes_at<=p_opens_at then raise exception 'Invalid quiz';end if;
 select count(*) into cnt from public.questions where id=any(p_question_ids) and status='approved';
 if cnt<>array_length(p_question_ids,1) or cnt<>(select count(distinct x) from unnest(p_question_ids) x) then raise exception 'Select unique approved questions';end if;
 insert into public.quizzes(title,kind,opens_at,closes_at,duration_minutes,published,created_by) values(p_title,p_kind,p_opens_at,p_closes_at,p_duration_minutes,true,auth.uid()) returning id into qid;
 insert into public.quiz_questions(quiz_id,question_id,position) select qid,x,ord::integer from unnest(p_question_ids) with ordinality as a(x,ord);
 return qid;
end $function$

CREATE OR REPLACE FUNCTION public.create_quiz_with_settings(p_title text, p_kind quiz_kind, p_question_ids uuid[], p_opens_at timestamp with time zone, p_closes_at timestamp with time zone, p_duration_minutes integer, p_result_visibility text DEFAULT 'immediate'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  qid uuid;
  cnt integer;
BEGIN
  IF NOT public.can_review() THEN
    RAISE EXCEPTION 'Only active teachers can create quizzes';
  END IF;
  IF coalesce(trim(p_title),'') = '' OR array_length(p_question_ids, 1) IS NULL OR p_closes_at <= p_opens_at THEN
    RAISE EXCEPTION 'Invalid quiz title or scheduling window';
  END IF;
  IF p_duration_minutes NOT BETWEEN 1 AND 180 OR p_result_visibility NOT IN ('immediate', 'after_release') THEN
    RAISE EXCEPTION 'Invalid quiz duration or result visibility settings';
  END IF;

  SELECT count(*) INTO cnt
  FROM public.questions
  WHERE id = ANY(p_question_ids) AND status = 'approved';

  IF cnt <> array_length(p_question_ids, 1) OR cnt <> (SELECT count(distinct x) FROM unnest(p_question_ids) x) THEN
    RAISE EXCEPTION 'Select unique, approved questions';
  END IF;

  INSERT INTO public.quizzes(
    title, kind, opens_at, closes_at, duration_minutes, published, created_by, result_visibility, results_published
  )
  VALUES (
    trim(p_title), p_kind, p_opens_at, p_closes_at, p_duration_minutes, true, auth.uid(), p_result_visibility, p_result_visibility = 'immediate'
  )
  RETURNING id INTO qid;

  INSERT INTO public.quiz_questions(quiz_id, question_id, position)
  SELECT qid, x, ord::integer
  FROM unnest(p_question_ids) WITH ORDINALITY AS a(x, ord);

  RETURN qid;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_duty(p_duty_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare existing public.duties%rowtype; c integer;
begin
  if not public.can_manage() then raise exception 'Not permitted'; end if;
  select target.* into existing from public.duties as target where target.id=p_duty_id for update;
  if not found then raise exception 'Duty not found'; end if;
  c:=existing.rotation_cycle;
  update public.duty_rotation_members as member set assigned_on=null
    where member.cycle_no=c and member.profile_id=existing.student_id and member.assigned_on=existing.duty_date;
  insert into public.duty_change_log(duty_id,action,old_student_id,reason,changed_by)
    values(existing.id,'deleted',existing.student_id,coalesce(nullif(trim(p_reason),''),'Deleted by staff'),auth.uid());
  delete from public.duties as target where target.id=existing.id;
end $function$

CREATE OR REPLACE FUNCTION public.delete_quiz_cascade(p_quiz_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT can_review() THEN
    RAISE EXCEPTION 'Access denied: Only teachers can delete quizzes';
  END IF;

  DELETE FROM public.quiz_attempts WHERE quiz_id = p_quiz_id;
  DELETE FROM public.quiz_attempt_starts WHERE quiz_id = p_quiz_id;
  DELETE FROM public.quiz_questions WHERE quiz_id = p_quiz_id;
  DELETE FROM public.quizzes WHERE id = p_quiz_id;

  RETURN jsonb_build_object('success', true, 'quiz_id', p_quiz_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.detach_question_from_duty(p_question_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cur_duty public.duties%rowtype;
begin
  select t.* into cur_duty from public.duties as t join public.duty_questions as dq on dq.duty_id=t.id where dq.question_id=p_question_id;
  if not found then raise exception 'That question is not linked to a duty'; end if;
  if not (public.can_review() or cur_duty.student_id=auth.uid()) then raise exception 'Not permitted'; end if;
  if cur_duty.duty_status='reviewed' and not public.can_review() then raise exception 'This duty is already reviewed'; end if;
  delete from public.duty_questions where question_id=p_question_id;
end $function$

CREATE OR REPLACE FUNCTION public.end_quiz_early(p_quiz_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_auto_submitted integer := 0;
  r RECORD;
  v_score integer;
  v_correct_count integer;
  v_wrong_count integer;
  v_skipped_count integer;
  v_total integer := 0;
  q_rec RECORD;
  v_answers jsonb;
  v_user_ans text;
  v_chosen_idx integer;
BEGIN
  IF NOT can_review() THEN
    RAISE EXCEPTION 'Access denied: Only teachers can end quizzes early';
  END IF;

  UPDATE public.quizzes
  SET ended_early_at = clock_timestamp()
  WHERE id = p_quiz_id;

  SELECT COUNT(*) INTO v_total FROM public.quiz_questions WHERE quiz_id = p_quiz_id;

  FOR r IN
    SELECT id, COALESCE(autosaved_answers, answers, '{}'::jsonb) AS user_answers
    FROM public.quiz_attempts
    WHERE quiz_id = p_quiz_id AND status = 'in_progress'
  LOOP
    v_score := 0;
    v_correct_count := 0;
    v_wrong_count := 0;
    v_skipped_count := 0;
    v_answers := r.user_answers;

    FOR q_rec IN
      SELECT q.id, q.correct_index
      FROM public.quiz_questions qq
      JOIN public.questions q ON q.id = qq.question_id
      WHERE qq.quiz_id = p_quiz_id
    LOOP
      v_user_ans := v_answers ->> q_rec.id::text;
      IF v_user_ans IS NULL OR v_user_ans = '' THEN
        v_skipped_count := v_skipped_count + 1;
      ELSE
        BEGIN
          v_chosen_idx := v_user_ans::integer;
          IF v_chosen_idx = q_rec.correct_index THEN
            v_score := v_score + 1;
            v_correct_count := v_correct_count + 1;
          ELSE
            v_wrong_count := v_wrong_count + 1;
          END IF;
        EXCEPTION WHEN OTHERS THEN
          v_wrong_count := v_wrong_count + 1;
        END;
      END IF;
    END LOOP;

    UPDATE public.quiz_attempts
    SET status = 'submitted',
        answers = v_answers,
        submitted_at = clock_timestamp(),
        score = v_score,
        total = v_total,
        correct_count = v_correct_count,
        wrong_count = v_wrong_count,
        skipped_count = v_skipped_count,
        updated_at = clock_timestamp()
    WHERE id = r.id;

    v_auto_submitted := v_auto_submitted + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'auto_submitted_count', v_auto_submitted);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_my_quiz_result(p_quiz_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a public.quiz_attempts%rowtype; q public.quizzes%rowtype; detail jsonb;
begin
  if public.current_role() not in ('student','student_leader') then raise exception 'Not permitted'; end if;
  select * into q from public.quizzes where id=p_quiz_id and published=true;
  select * into a from public.quiz_attempts where quiz_id=p_quiz_id and student_id=auth.uid();
  if not found then raise exception 'No submitted attempt found'; end if;
  if q.result_visibility='after_release' and not q.results_published then raise exception 'Results have not been published yet'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',questions.id,'stem',questions.stem,'topic',questions.topic,'options',questions.options,
    'selected_index',case when a.answers ? questions.id::text then (a.answers->>questions.id::text)::integer else null end,
    'correct_index',questions.correct_index,'is_correct',(a.answers->>questions.id::text)=questions.correct_index::text,
    'explanation',questions.explanation,'source',questions.source_url
  ) order by qq.position),'[]'::jsonb) into detail
  from public.quiz_questions qq join public.questions on questions.id=qq.question_id where qq.quiz_id=p_quiz_id;
  return jsonb_build_object('quiz_id',q.id,'title',q.title,'score',a.score,'total',a.total,'submitted_at',a.submitted_at,'questions',detail);
end $function$

CREATE OR REPLACE FUNCTION public.get_my_quiz_summary()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_eligible integer := 0;
  v_attended integer := 0;
  v_marks_got integer := 0;
  v_marks_total integer := 0;
  v_pending integer := 0;
  v_pct integer := 0;
BEGIN
  SELECT count(*) INTO v_eligible
  FROM public.quizzes
  WHERE published = true AND opens_at <= clock_timestamp();

  SELECT 
    count(qa.id),
    COALESCE(sum(CASE 
      WHEN q.result_visibility = 'after_release' AND NOT q.results_published THEN 0 
      ELSE qa.score 
    END), 0),
    COALESCE(sum(CASE 
      WHEN q.result_visibility = 'after_release' AND NOT q.results_published THEN 0 
      ELSE qa.total 
    END), 0),
    count(*) FILTER (WHERE q.result_visibility = 'after_release' AND NOT q.results_published)
  INTO v_attended, v_marks_got, v_marks_total, v_pending
  FROM public.quiz_attempts qa
  JOIN public.quizzes q ON q.id = qa.quiz_id
  WHERE qa.student_id = v_uid AND qa.status = 'submitted';

  IF v_marks_total > 0 THEN
    v_pct := round((v_marks_got::numeric / v_marks_total::numeric) * 100);
  END IF;

  RETURN json_build_object(
    'eligible', v_eligible,
    'attended', v_attended,
    'marks_got', v_marks_got,
    'marks_total', v_marks_total,
    'percent', v_pct,
    'pending_results', v_pending
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_question_bank(p_search text DEFAULT NULL::text, p_topic text DEFAULT NULL::text, p_author_id text DEFAULT NULL::text, p_only_mine boolean DEFAULT false, p_status text DEFAULT NULL::text, p_is_special boolean DEFAULT NULL::boolean, p_date_from text DEFAULT NULL::text, p_date_to text DEFAULT NULL::text, p_has_source boolean DEFAULT NULL::boolean, p_quiz_usage text DEFAULT NULL::text, p_sort text DEFAULT 'newest'::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_id uuid := auth.uid();
  v_is_staff boolean := false;
  v_author_uuid uuid := null;
  v_status_enum question_status := null;
  v_date_from date := null;
  v_date_to date := null;
  v_total integer := 0;
  v_questions json := '[]'::json;
  v_uploaders json := '[]'::json;
begin
  if v_caller_id is null or not public.is_active() then
    raise exception 'Not permitted';
  end if;

  v_is_staff := coalesce(public.can_review(), false);

  if p_author_id is not null and trim(p_author_id) not in ('', 'all') then
    begin
      v_author_uuid := trim(p_author_id)::uuid;
    exception when others then
      v_author_uuid := null;
    end;
  end if;

  if p_status is not null and trim(p_status) not in ('', 'all') then
    begin
      v_status_enum := trim(p_status)::question_status;
    exception when others then
      v_status_enum := null;
    end;
  end if;

  if p_date_from is not null and trim(p_date_from) <> '' then
    begin
      v_date_from := trim(p_date_from)::date;
    exception when others then
      v_date_from := null;
    end;
  end if;

  if p_date_to is not null and trim(p_date_to) <> '' then
    begin
      v_date_to := trim(p_date_to)::date;
    exception when others then
      v_date_to := null;
    end;
  end if;

  select coalesce(json_agg(row_to_json(u)), '[]'::json)
  into v_uploaders
  from (
    select distinct p.id, p.full_name, p.enrollment_number
    from public.questions q
    join public.profiles p on p.id = q.author_id
    where (
      v_is_staff
      or public.question_visible_to_me(q.id, q.author_id, q.status)
    )
    order by p.full_name asc
  ) u;

  select count(*)
  into v_total
  from public.questions q
  left join public.profiles a on a.id = q.author_id
  where (
      v_is_staff
      or public.question_visible_to_me(q.id, q.author_id, q.status)
    )
    and (not coalesce(p_only_mine, false) or q.author_id = v_caller_id)
    and (v_author_uuid is null or q.author_id = v_author_uuid)
    and (v_status_enum is null or q.status = v_status_enum)
    and (p_topic is null or p_topic = 'all' or q.topic = p_topic)
    and (
      p_is_special is null
      or not v_is_staff
      or q.is_special = p_is_special
    )
    and (v_date_from is null or q.created_at::date >= v_date_from)
    and (v_date_to is null or q.created_at::date <= v_date_to)
    and (
      p_has_source is null
      or (p_has_source and q.source_url is not null and trim(q.source_url) <> '')
      or (not p_has_source and (q.source_url is null or trim(q.source_url) = ''))
    )
    and (
      p_quiz_usage is null
      or p_quiz_usage = 'all'
      or not v_is_staff
      or (
        p_quiz_usage = 'used'
        and exists (
          select 1 from public.quiz_questions qq where qq.question_id = q.id
        )
      )
      or (
        p_quiz_usage = 'unused'
        and not exists (
          select 1 from public.quiz_questions qq where qq.question_id = q.id
        )
      )
    )
    and (
      p_search is null
      or trim(p_search) = ''
      or q.stem ilike '%' || trim(p_search) || '%'
      or q.explanation ilike '%' || trim(p_search) || '%'
      or q.source_url ilike '%' || trim(p_search) || '%'
      or q.options::text ilike '%' || trim(p_search) || '%'
    );

  select coalesce(json_agg(row_data), '[]'::json)
  into v_questions
  from (
    select
      q.id,
      q.stem,
      q.topic,
      q.options,
      q.correct_index,
      q.explanation,
      q.source_url,
      q.status,
      q.author_id,
      q.created_at,
      q.is_special,
      exists (
        select 1 from public.quiz_questions qq where qq.question_id = q.id
      ) as is_used_in_quiz,
      json_build_object(
        'full_name', a.full_name,
        'enrollment_number', a.enrollment_number
      ) as author
    from public.questions q
    left join public.profiles a on a.id = q.author_id
    where (
        v_is_staff
        or public.question_visible_to_me(q.id, q.author_id, q.status)
      )
      and (not coalesce(p_only_mine, false) or q.author_id = v_caller_id)
      and (v_author_uuid is null or q.author_id = v_author_uuid)
      and (v_status_enum is null or q.status = v_status_enum)
      and (p_topic is null or p_topic = 'all' or q.topic = p_topic)
      and (
        p_is_special is null
        or not v_is_staff
        or q.is_special = p_is_special
      )
      and (v_date_from is null or q.created_at::date >= v_date_from)
      and (v_date_to is null or q.created_at::date <= v_date_to)
      and (
        p_has_source is null
        or (p_has_source and q.source_url is not null and trim(q.source_url) <> '')
        or (not p_has_source and (q.source_url is null or trim(q.source_url) = ''))
      )
      and (
        p_quiz_usage is null
        or p_quiz_usage = 'all'
        or not v_is_staff
        or (
          p_quiz_usage = 'used'
          and exists (
            select 1 from public.quiz_questions qq where qq.question_id = q.id
          )
        )
        or (
          p_quiz_usage = 'unused'
          and not exists (
            select 1 from public.quiz_questions qq where qq.question_id = q.id
          )
        )
      )
      and (
        p_search is null
        or trim(p_search) = ''
        or q.stem ilike '%' || trim(p_search) || '%'
        or q.explanation ilike '%' || trim(p_search) || '%'
        or q.source_url ilike '%' || trim(p_search) || '%'
        or q.options::text ilike '%' || trim(p_search) || '%'
      )
    order by
      case when p_sort = 'oldest' then q.created_at end asc,
      case when p_sort = 'topic' then q.topic end asc,
      case when p_sort = 'uploader' then a.full_name end asc,
      case when p_sort = 'status' then q.status::text end asc,
      q.created_at desc
    limit p_limit
    offset p_offset
  ) row_data;

  return json_build_object(
    'total', v_total,
    'uploaders', v_uploaders,
    'questions', v_questions
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.normalize_profile_enrollment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.enrollment_number := nullif(btrim(NEW.enrollment_number), '');
  IF NEW.role = 'supervisor' THEN
    NEW.enrollment_number := NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.publish_quiz_results(p_quiz_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT can_review() THEN
    RAISE EXCEPTION 'Access denied: Only teachers can publish quiz results';
  END IF;

  UPDATE public.quizzes
  SET results_published = true
  WHERE id = p_quiz_id;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.question_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op='INSERT' then
    new.author_id:=auth.uid();
    new.status:='pending';
    new.reviewed_by:=null;
    new.reviewed_at:=null;
    if not public.can_review() then new.is_special:=false; end if;
  elsif public.can_review() then
    if old.author_id is distinct from new.author_id then new.author_id:=old.author_id; end if;
    if old.status is distinct from new.status then
      new.reviewed_by:=auth.uid();
      new.reviewed_at:=now();
    else
      new.reviewed_by:=old.reviewed_by;
      new.reviewed_at:=old.reviewed_at;
    end if;
  else
    new.author_id:=old.author_id;
    new.status:='pending';
    new.reviewed_by:=null;
    new.reviewed_at:=null;
    new.is_special:=old.is_special;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.reassign_duty(p_duty_date date, p_student_id uuid, p_reason text)
 RETURNS TABLE(duty_id uuid, duty_date date, student_id uuid, full_name text, target_count integer, rotation_cycle integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare current_duty public.duties%rowtype; c integer; old_student uuid; clean_reason text;
begin
  if not public.can_manage() then raise exception 'Not permitted'; end if;
  clean_reason:=nullif(trim(p_reason),'');
  if clean_reason is null then raise exception 'Add a short reason for changing this assignment'; end if;

  select existing.* into current_duty
  from public.duties as existing
  where existing.duty_date=p_duty_date
  for update;
  if not found then raise exception 'No duty is assigned for this date'; end if;

  insert into public.duty_rotation_state(singleton,current_cycle)
  values(true,coalesce(current_duty.rotation_cycle,1)) on conflict(singleton) do nothing;
  perform 1 from public.duty_rotation_state as rotation where rotation.singleton=true for update;
  select rotation.current_cycle into c from public.duty_rotation_state as rotation where rotation.singleton=true;
  c:=coalesce(current_duty.rotation_cycle,c,1);
  old_student:=current_duty.student_id;

  if p_student_id=old_student then raise exception 'Choose a different student or keep the current assignment'; end if;
  if not exists(select 1 from public.profiles as member where member.id=p_student_id and member.active and member.role in ('student','student_leader')) then
    raise exception 'Choose an active student';
  end if;
  if exists(select 1 from public.duty_availability as availability
    where availability.profile_id=p_student_id and availability.availability_date=p_duty_date
      and availability.status in ('leave','unavailable')) then
    raise exception 'This student is unavailable for that date';
  end if;
  if exists(select 1 from public.duty_rotation_members as rotation_member
    where rotation_member.cycle_no=c and rotation_member.profile_id=p_student_id and rotation_member.assigned_on is not null) then
    raise exception 'This student already had a turn in the current rotation';
  end if;

  insert into public.duty_rotation_members(cycle_no,profile_id,position)
  select c,p_student_id,coalesce((select max(existing.position)+1 from public.duty_rotation_members as existing where existing.cycle_no=c),1)
  where not exists(select 1 from public.duty_rotation_members as existing where existing.cycle_no=c and existing.profile_id=p_student_id);

  update public.duty_rotation_members as rotation_member
    set assigned_on=null where rotation_member.cycle_no=c and rotation_member.profile_id=old_student;
  update public.duties as target
    set student_id=p_student_id,assigned_by=auth.uid(),duty_status='assigned',status_note=clean_reason,
        status_updated_at=now(),status_updated_by=auth.uid()
    where target.id=current_duty.id;
  update public.duty_rotation_members as rotation_member
    set assigned_on=p_duty_date where rotation_member.cycle_no=c and rotation_member.profile_id=p_student_id;
  insert into public.duty_change_log(duty_id,action,old_student_id,new_student_id,reason,changed_by)
    values(current_duty.id,'reassigned',old_student,p_student_id,clean_reason,auth.uid());

  return query select current_duty.id,current_duty.duty_date,member.id,member.full_name,current_duty.target_count,c
    from public.profiles as member where member.id=p_student_id;
end $function$

CREATE OR REPLACE FUNCTION public.recalculate_quiz_scores(p_quiz_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sub RECORD;
  v_q RECORD;
  v_chosen_str TEXT;
  v_chosen_idx INT;
  v_correct INT;
  v_wrong INT;
  v_skipped INT;
  v_total INT := 0;
  v_count INT := 0;
  v_ans JSONB;
BEGIN
  IF NOT can_review() THEN
    RAISE EXCEPTION 'Access denied: Only teachers can recalculate scores';
  END IF;

  SELECT COUNT(*) INTO v_total FROM public.quiz_questions WHERE quiz_id = p_quiz_id;

  FOR v_sub IN 
    SELECT id, COALESCE(answers, autosaved_answers, '{}'::jsonb) AS user_answers
    FROM public.quiz_attempts 
    WHERE quiz_id = p_quiz_id
  LOOP
    v_correct := 0;
    v_wrong := 0;
    v_skipped := 0;
    v_ans := v_sub.user_answers;

    FOR v_q IN 
      SELECT q.id, q.correct_index
      FROM public.quiz_questions qq
      JOIN public.questions q ON qq.question_id = q.id
      WHERE qq.quiz_id = p_quiz_id
    LOOP
      v_chosen_str := v_ans ->> v_q.id::text;
      
      IF v_chosen_str IS NULL OR v_chosen_str = '' THEN
        v_skipped := v_skipped + 1;
      ELSE
        BEGIN
          v_chosen_idx := v_chosen_str::int;
          IF v_chosen_idx = v_q.correct_index THEN
            v_correct := v_correct + 1;
          ELSE
            v_wrong := v_wrong + 1;
          END IF;
        EXCEPTION WHEN OTHERS THEN
          v_wrong := v_wrong + 1;
        END;
      END IF;
    END LOOP;

    UPDATE public.quiz_attempts
    SET 
      score = v_correct,
      total = v_total,
      correct_count = v_correct,
      wrong_count = v_wrong,
      skipped_count = v_skipped,
      updated_at = clock_timestamp()
    WHERE id = v_sub.id;

    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'quiz_id', p_quiz_id, 'updated_submissions', v_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_duty_status(p_duty_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cur_duty public.duties%rowtype; uploaded integer; approved integer; need integer; cur integer; nxt text;
  names constant text[]:=array['assigned','confirmed','in_progress','submitted','reviewed'];
begin
  select t.* into cur_duty from public.duties as t where t.id=p_duty_id for update;
  if not found then return; end if;
  cur:=array_position(names,cur_duty.duty_status);
  if cur is null then return; end if;   -- excused / missed / change_requested stay as set by a person

  select count(*),count(*) filter(where q.status='approved') into uploaded,approved
  from public.duty_questions as dq join public.questions as q on q.id=dq.question_id
  where dq.duty_id=cur_duty.id and q.author_id=cur_duty.student_id;

  need:=case when approved>=cur_duty.target_count then 5
             when uploaded>=cur_duty.target_count then 4
             when uploaded>=1 then 3 else 1 end;

  if need>cur then
    nxt:=names[need];
  elsif cur>=4 and uploaded<cur_duty.target_count then
    nxt:=case when uploaded>=1 then 'in_progress' else 'confirmed' end;      -- questions were removed
  elsif cur=5 and cur_duty.status_updated_by is null and need<5 then
    nxt:=names[greatest(need,2)];                                              -- an approval was withdrawn
  else
    return;
  end if;

  if nxt is distinct from cur_duty.duty_status then
    update public.duties as t set duty_status=nxt,status_note=null,status_updated_at=now(),status_updated_by=null where t.id=cur_duty.id;
    insert into public.duty_change_log(duty_id,action,old_student_id,new_student_id,reason,changed_by)
      values(cur_duty.id,'status:'||nxt,cur_duty.student_id,cur_duty.student_id,'Automatic, based on the questions added and approved',null);
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.save_duty(p_duty_id uuid, p_duty_date date, p_student_id uuid, p_target_count integer, p_reason text DEFAULT NULL::text)
 RETURNS TABLE(duty_id uuid, duty_date date, student_id uuid, full_name text, target_count integer, rotation_cycle integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare existing public.duties%rowtype; c integer; clean_reason text; changed_student boolean;
begin
  if not public.can_manage() then raise exception 'Not permitted'; end if;
  if p_duty_date is null or p_target_count not between 1 and 20 then raise exception 'Choose a valid date and question target'; end if;
  select target.* into existing from public.duties as target where target.id=p_duty_id for update;
  if not found then raise exception 'Duty not found'; end if;
  if exists(select 1 from public.duties as conflict where conflict.duty_date=p_duty_date and conflict.id<>existing.id) then
    raise exception 'Another duty already exists for this date';
  end if;
  if not exists(select 1 from public.profiles as member where member.id=p_student_id and member.active and member.role in ('student','student_leader')) then
    raise exception 'Choose an active student';
  end if;

  insert into public.duty_rotation_state(singleton,current_cycle) values(true,coalesce(existing.rotation_cycle,1)) on conflict(singleton) do nothing;
  perform 1 from public.duty_rotation_state as rotation where rotation.singleton=true for update;
  select rotation.current_cycle into c from public.duty_rotation_state as rotation where rotation.singleton=true;
  c:=coalesce(existing.rotation_cycle,c,1);
  changed_student:=p_student_id<>existing.student_id;
  insert into public.duty_rotation_members(cycle_no,profile_id,position)
    select c,p_student_id,coalesce((select max(member.position)+1 from public.duty_rotation_members as member where member.cycle_no=c),1)
    where not exists(select 1 from public.duty_rotation_members as member where member.cycle_no=c and member.profile_id=p_student_id);
  if changed_student and exists(select 1 from public.duty_rotation_members as member where member.cycle_no=c and member.profile_id=p_student_id and member.assigned_on is not null) then
    raise exception 'This student already had a turn in the current rotation';
  end if;

  if changed_student then
    update public.duty_rotation_members as member set assigned_on=null where member.cycle_no=c and member.profile_id=existing.student_id;
  end if;
  update public.duty_rotation_members as member set assigned_on=p_duty_date where member.cycle_no=c and member.profile_id=p_student_id;
  clean_reason:=nullif(trim(p_reason),'');
  update public.duties as target set duty_date=p_duty_date,student_id=p_student_id,target_count=p_target_count,assigned_by=auth.uid(),
    duty_status=case when changed_student then 'assigned' else target.duty_status end,
    status_note=coalesce(clean_reason,target.status_note),status_updated_at=case when changed_student then now() else target.status_updated_at end,
    status_updated_by=case when changed_student then auth.uid() else target.status_updated_by end
    where target.id=existing.id;
  insert into public.duty_change_log(duty_id,action,old_student_id,new_student_id,reason,changed_by)
    values(existing.id,case when changed_student then 'reassigned' else 'edited' end,existing.student_id,p_student_id,clean_reason,auth.uid());
  return query select existing.id,p_duty_date,p.id,p.full_name,p_target_count,c from public.profiles as p where p.id=p_student_id;
end $function$

CREATE OR REPLACE FUNCTION public.start_quiz(p_quiz_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_quiz RECORD;
  v_attempt RECORD;
  v_started_at timestamptz;
BEGIN
  SELECT role::text INTO v_role
  FROM public.profiles
  WHERE id = v_uid AND active = true;

  IF v_role NOT IN ('student', 'student_leader') THEN
    RAISE EXCEPTION 'Only active participants can take quizzes.';
  END IF;

  SELECT * INTO v_quiz FROM public.quizzes WHERE id = p_quiz_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Quiz not found.';
  END IF;

  IF NOT v_quiz.published THEN
    RAISE EXCEPTION 'This quiz is not published.';
  END IF;

  IF v_quiz.ended_early_at IS NOT NULL OR clock_timestamp() > v_quiz.closes_at THEN
    RAISE EXCEPTION 'This quiz has closed.';
  END IF;

  SELECT * INTO v_attempt FROM public.quiz_attempts
  WHERE quiz_id = p_quiz_id AND student_id = v_uid;

  IF FOUND THEN
    IF v_attempt.status = 'submitted' THEN
      RAISE EXCEPTION 'You have already submitted this quiz.';
    END IF;
    RETURN jsonb_build_object(
      'status', 'in_progress',
      'started_at', v_attempt.started_at,
      'autosaved_answers', COALESCE(v_attempt.autosaved_answers, '{}'::jsonb)
    );
  END IF;

  v_started_at := clock_timestamp();

  INSERT INTO public.quiz_attempts (
    quiz_id, student_id, started_at, status, autosaved_answers
  ) VALUES (
    p_quiz_id, v_uid, v_started_at, 'in_progress', '{}'::jsonb
  );

  INSERT INTO public.quiz_attempt_starts (
    quiz_id, student_id, started_at
  ) VALUES (
    p_quiz_id, v_uid, v_started_at
  ) ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object(
    'status', 'started',
    'started_at', v_started_at,
    'autosaved_answers', '{}'::jsonb
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_quiz(p_quiz_id uuid, p_answers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_student_id uuid;
  v_total int := 0;
  v_correct int := 0;
  v_wrong int := 0;
  v_skipped int := 0;
  v_q record;
  v_chosen_str text;
  v_chosen_idx int;
  v_effective_answers jsonb;
  v_saved_answers jsonb;
begin
  v_student_id := auth.uid();
  if v_student_id is null then
    raise exception 'Not authenticated';
  end if;
  if p_answers is not null and jsonb_typeof(p_answers) <> 'object' then
    raise exception 'Answers must be an object';
  end if;

  select coalesce(autosaved_answers, '{}'::jsonb)
  into v_saved_answers
  from public.quiz_attempts
  where quiz_id = p_quiz_id and student_id = v_student_id;

  v_effective_answers :=
    coalesce(v_saved_answers, '{}'::jsonb)
    || coalesce(p_answers, '{}'::jsonb);

  select count(*) into v_total
  from public.quiz_questions
  where quiz_id = p_quiz_id;

  for v_q in
    select q.id, q.correct_index
    from public.quiz_questions qq
    join public.questions q on q.id = qq.question_id
    where qq.quiz_id = p_quiz_id
  loop
    v_chosen_str := v_effective_answers ->> v_q.id::text;
    if v_chosen_str is null or v_chosen_str = '' then
      v_skipped := v_skipped + 1;
    else
      begin
        v_chosen_idx := v_chosen_str::int;
        if v_chosen_idx = v_q.correct_index then
          v_correct := v_correct + 1;
        else
          v_wrong := v_wrong + 1;
        end if;
      exception when others then
        v_wrong := v_wrong + 1;
      end;
    end if;
  end loop;

  insert into public.quiz_attempts (
    quiz_id,
    student_id,
    status,
    answers,
    autosaved_answers,
    score,
    total,
    correct_count,
    wrong_count,
    skipped_count,
    submitted_at,
    updated_at
  )
  values (
    p_quiz_id,
    v_student_id,
    'submitted',
    v_effective_answers,
    v_effective_answers,
    v_correct,
    v_total,
    v_correct,
    v_wrong,
    v_skipped,
    clock_timestamp(),
    clock_timestamp()
  )
  on conflict (quiz_id, student_id) do update set
    status = 'submitted',
    answers = excluded.answers,
    autosaved_answers = excluded.autosaved_answers,
    score = excluded.score,
    total = excluded.total,
    correct_count = excluded.correct_count,
    wrong_count = excluded.wrong_count,
    skipped_count = excluded.skipped_count,
    submitted_at = clock_timestamp(),
    updated_at = clock_timestamp();

  return jsonb_build_object(
    'success', true,
    'status', 'submitted',
    'score', v_correct,
    'total', v_total
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.swap_duties(p_duty_a uuid, p_duty_b uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  dut_a public.duties%rowtype; dut_b public.duties%rowtype; clean_reason text; name_a text; name_b text;
  today_ist date:=(now() at time zone 'Asia/Kolkata')::date;
  parked constant date:=date '0001-01-01';
begin
  if not public.can_manage() then raise exception 'Not permitted'; end if;
  if p_duty_a is null or p_duty_b is null or p_duty_a=p_duty_b then raise exception 'Choose two different duties'; end if;
  perform 1 from public.duties as locked where locked.id in (p_duty_a,p_duty_b) order by locked.id for update;
  select t.* into dut_a from public.duties as t where t.id=p_duty_a;
  if not found then raise exception 'Duty not found'; end if;
  select t.* into dut_b from public.duties as t where t.id=p_duty_b;
  if not found then raise exception 'Duty not found'; end if;
  if dut_a.student_id=dut_b.student_id then raise exception 'Both duties belong to the same student'; end if;
  if dut_a.duty_date<today_ist or dut_b.duty_date<today_ist then raise exception 'Only today''s and upcoming duties can be swapped'; end if;
  if dut_a.duty_status in ('submitted','reviewed','excused','missed') or dut_b.duty_status in ('submitted','reviewed','excused','missed') then
    raise exception 'A duty that is already submitted, reviewed, excused or missed cannot be swapped';
  end if;
  select f.full_name into name_a from public.profiles as f where f.id=dut_a.student_id;
  select f.full_name into name_b from public.profiles as f where f.id=dut_b.student_id;
  if exists(select 1 from public.duty_availability as av where av.profile_id=dut_a.student_id and av.availability_date=dut_b.duty_date and av.status in ('leave','unavailable')) then
    raise exception '% is marked unavailable on %',name_a,dut_b.duty_date;
  end if;
  if exists(select 1 from public.duty_availability as av where av.profile_id=dut_b.student_id and av.availability_date=dut_a.duty_date and av.status in ('leave','unavailable')) then
    raise exception '% is marked unavailable on %',name_b,dut_a.duty_date;
  end if;

  clean_reason:=coalesce(nullif(trim(p_reason),''),'Swapped by staff');
  -- duty_date is unique, so park one duty while the dates trade places
  update public.duties as t set duty_date=parked where t.id=dut_a.id;
  update public.duties as t set duty_date=dut_a.duty_date,duty_status='assigned',status_note=clean_reason,
    status_updated_at=now(),status_updated_by=auth.uid(),assigned_by=auth.uid() where t.id=dut_b.id;
  update public.duties as t set duty_date=dut_b.duty_date,duty_status='assigned',status_note=clean_reason,
    status_updated_at=now(),status_updated_by=auth.uid(),assigned_by=auth.uid() where t.id=dut_a.id;

  update public.duty_rotation_members as m set assigned_on=dut_b.duty_date where m.cycle_no=dut_a.rotation_cycle and m.profile_id=dut_a.student_id;
  update public.duty_rotation_members as m set assigned_on=dut_a.duty_date where m.cycle_no=dut_b.rotation_cycle and m.profile_id=dut_b.student_id;

  insert into public.duty_change_log(duty_id,action,old_student_id,new_student_id,reason,changed_by)
    values(dut_a.id,'swapped',dut_a.student_id,dut_b.student_id,clean_reason,auth.uid()),
          (dut_b.id,'swapped',dut_b.student_id,dut_a.student_id,clean_reason,auth.uid());
end $function$

CREATE OR REPLACE FUNCTION public.update_duty_status(p_duty_id uuid, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  current_duty public.duties%rowtype;
  clean_reason text;
  is_reviewer boolean;
  uploaded integer;
BEGIN
  IF NOT public.is_active() THEN
    RAISE EXCEPTION 'Active account required';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('assigned','confirmed','in_progress','submitted','reviewed','change_requested','excused','missed') THEN
    RAISE EXCEPTION 'Choose a valid duty status';
  END IF;

  SELECT target.* INTO current_duty
  FROM public.duties AS target
  WHERE target.id = p_duty_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Duty not found';
  END IF;

  is_reviewer := public.can_review();
  IF NOT is_reviewer THEN
    IF current_duty.student_id <> auth.uid() THEN
      RAISE EXCEPTION 'Only a teacher can change another student''s duty status';
    END IF;
    IF p_status NOT IN ('confirmed', 'in_progress', 'submitted', 'change_requested') THEN
      RAISE EXCEPTION 'Students can confirm, start, submit, or request a change';
    END IF;
  END IF;

  clean_reason := nullif(trim(p_reason), '');
  IF p_status = 'change_requested' AND clean_reason IS NULL THEN
    RAISE EXCEPTION 'Add a short reason for the urgent change request';
  END IF;

  IF p_status IN ('submitted', 'reviewed') THEN
    SELECT count(*) INTO uploaded
    FROM public.duty_questions AS dq
    JOIN public.questions AS q ON q.id = dq.question_id
    WHERE dq.duty_id = current_duty.id AND q.author_id = current_duty.student_id;

    IF uploaded < current_duty.target_count THEN
      RAISE EXCEPTION 'Only % of % questions are added to this duty', uploaded, current_duty.target_count;
    END IF;
  END IF;

  UPDATE public.duties AS target
  SET duty_status = p_status,
      status_note = CASE WHEN clean_reason IS NOT NULL THEN clean_reason ELSE NULL END,
      status_updated_at = clock_timestamp(),
      status_updated_by = auth.uid()
  WHERE target.id = current_duty.id;

  INSERT INTO public.duty_change_log(duty_id, action, old_student_id, new_student_id, reason, changed_by)
  VALUES (
    current_duty.id,
    'status:' || p_status,
    current_duty.student_id,
    current_duty.student_id,
    clean_reason,
    auth.uid()
  );
END;
$function$
